window.RXP.push(
/* ===== GASTROENTEROLOGIA ===== */
{n:'Gastroenterite aguda / desidratação (criança)',cid:'A09 / E86',sp:'Gastroenterologia pediátrica',ps:[{v:'VO / EV / SNG',i:['CLASSIFICAR (OMS/MS): SEM desidratação (alerta, olhos normais, bebe normalmente, prega desfaz rápido) → PLANO A; DESIDRATAÇÃO (≥ 2: inquieta/irritada, olhos fundos, bebe ávida/com sede, prega lenta < 2 s; perda 5–9%) → PLANO B; GRAVE (≥ 2: letárgica/inconsciente, olhos muito fundos, não consegue beber, prega muito lenta > 2 s; perda ≥ 10%; choque) → PLANO C','PLANO B (no serviço): SRO {{v;75;}} (75 mL/kg — 50–100) em 4 h, em pequenos volumes frequentes (colher/copo/seringa a cada 1–2 min); reavaliar a cada 1 h; ONDANSETRONA dose única VO/EV ↓ vômitos e necessidade de EV: {{p;8–15 kg: 2 mg · 15–30 kg: 4 mg · > 30 kg: 8 mg}} (0,15 mg/kg = {{d;0.15;0.8;8;mL}} da solução 4 mg/5 mL; comprimido orodispersível) — não repetir de rotina; se vomitar SRO: aguardar 10 min e reiniciar mais devagar; SNG (gastróclise 20–30 mL/kg/h) se recusa/vômitos persistentes; após 4 h: hidratada → plano A; ainda desidratada → repetir plano B; piora → plano C','PLANO C (grave/choque): Ringer lactato ou SF 0,9% EV/IO — fase RÁPIDA: < 1 ano: {{v;30;}} (30 mL/kg) em 1 h + {{v;70;}} (70 mL/kg) em 5 h; ≥ 1 ano: {{v;30;}} em 30 min + {{v;70;}} em 2,5 h (OMS); alternativa (MS/SBP — expansão): SF 0,9% {{v;20;}} (20 mL/kg) em 20–30 min, repetir até 3× até melhorar perfusão/pulso; reavaliar a cada 15–30 min; iniciar SRO 5 mL/kg/h assim que conseguir beber; depois manutenção isotônica (SG 5% + NaCl 0,9% + KCl 20 mEq/L) se não tolerar VO; glicemia, eletrólitos, gasometria, creatinina se grave/convulsão/alteração neurológica/desnutrido (hipernatremia: corrigir lentamente ≤ 0,5 mEq/L/h)','ZINCO para TODA diarreia aguda (OMS/MS — ↓ duração/gravidade, principalmente em desnutridos/países em desenvolvimento): < 6 meses: 10 mg/dia; ≥ 6 meses: 20 mg/dia por 10–14 dias','Antibiótico APENAS: disenteria (sangue + febre/toxemia — Shigella: azitromicina 10 mg/kg/dia 3 d ou ceftriaxona), cólera suspeita, imunossuprimido, < 3 meses com suspeita bacteriana (internar), sepse; NÃO para diarreia aquosa; evitar em E. coli O157 (SHU)','NÃO usar: loperamida (contraindicada < 12 anos — íleo/morte), difenoxilato, antiespasmódicos, "adsorventes"/caulim, racecadotrila (benefício modesto; opcional), antieméticos além da ondansetrona (metoclopramida/dimenidrinato — extrapiramidal/sedação), refrigerante/suco industrializado/isotônico de esportista como reidratação','Probióticos: evidência atual NÃO sustenta uso de rotina (Schnadower/Freedman NEJM 2018; Cochrane 2020); S. boulardii/L. rhamnosus GG podem reduzir ~1 dia em alguns contextos — opcional; manter aleitamento materno e dieta habitual (não há benefício de "dieta branda"/retirar lactose exceto se diarreia prolongada)','INTERNAR: plano C, falha do plano B (vômitos incoercíveis/recusa/piora), < 2–3 meses, desnutrição grave, alteração neurológica, suspeita de abdome cirúrgico (dor intensa/localizada, distensão, vômitos biliosos, massa, sangue em "geleia de framboesa" — intussuscepção), diarreia com sangue em < 1 ano, distúrbio eletrolítico (Na < 130/> 150, K < 3), comorbidade, suspeita de SHU (palidez, oligúria, petéquias), família sem condições']}],casa:[{v:'USO ORAL',i:[['Soro de reidratação oral (SRO — envelope OMS 75 mEq/L de Na / osmolaridade reduzida)','6–10 envelopes','Diluir 1 envelope em 1 LITRO de água filtrada/fervida (fria); validade 24 h. PLANO A: oferecer após cada evacuação líquida ou vômito: < 1 ano: 50–100 mL (¼–½ copo); 1–10 anos: 100–200 mL; > 10 anos: à vontade — em colher/copo, aos poucos; continuar enquanto durar a diarreia. Se a criança vomitar: esperar 10 min e oferecer mais devagar'],['Zinco (sulfato/gluconato) xarope 10 mg/5 mL ou comprimido 10/20 mg','1 frasco / 14 comprimidos','Dar {{p;< 6 meses: 10 mg (5 mL) · ≥ 6 meses: 20 mg (10 mL)}} 1×/dia por 10–14 dias (mesmo após parar a diarreia)'],['Ondansetrona solução 4 mg/5 mL (0,8 mg/mL) ou comprimido orodispersível 4 mg — SOMENTE se vômitos impedirem a hidratação (≥ 6 meses)','1 frasco / 4 comprimidos','Dar {{d;0.15;0.8;8;mL}} (0,15 mg/kg; máx. 8 mg) de 8/8 h APENAS se vomitar e não conseguir beber, por no máximo 2 dias; aguardar 15–30 min e oferecer SRO'],['Dipirona gotas 500 mg/mL (≥ 3 m) ou Paracetamol gotas 200 mg/mL','1 frasco','Dar {{d;15;25;1000;gotas}} (dipirona) ou {{d;13;13.3;750;gotas}} (paracetamol) de 6/6 h se febre/dor/desconforto'],['Azitromicina 200 mg/5 mL — APENAS se diarreia com SANGUE + febre (disenteria), prescrita após avaliação','1 frasco','Dar {{d;10;40;500;mL}} 1×/dia por 3 dias']]}],ori:['PLANO A em casa: (1) mais líquidos que o habitual — SRO, água, leite materno, sopas, água de arroz, água de coco; NÃO refrigerante, suco de caixinha, "isotônico" de academia, chá de ervas (muito açúcar/pouco sal — pioram); (2) MANTER A ALIMENTAÇÃO normal e o aleitamento (mais vezes, menor volume) — não fazer jejum nem "dieta de arroz" prolongada; evitar só frituras/doces/sucos concentrados; retomar alimentação plena assim que a criança aceitar; (3) ZINCO por 10–14 dias; (4) reconhecer SINAIS DE DESIDRATAÇÃO e voltar','Diarreia viral dura 3–7 dias (rotavírus até 7–10) e vômitos 1–2 dias; fezes podem ficar amolecidas por 1–2 semanas; não precisa de exame de fezes de rotina','Lavar as mãos com água e sabão (após trocar fralda, antes de preparar alimentos — a família toda), lavar bem alimentos, água filtrada/fervida, descartar fraldas em saco fechado, limpar superfícies; afastar da creche até 24–48 h sem diarreia/vômito','Preparar o SRO corretamente: 1 envelope em 1 L (nunca em menos água — hipernatremia); não acrescentar açúcar; manter tampado, descartar após 24 h; SRO caseiro (1 L de água + 1 colher de chá rasa de sal + 2 colheres de sopa de açúcar) só se não houver o envelope','Vacina rotavírus em dia (2 e 4 meses); retorno em 24–48 h para reavaliar hidratação ou antes se sinais de alarme'],al:['Sinais de DESIDRATAÇÃO: muita sede, boca/língua secas, olhos fundos, chora sem lágrimas, moleira funda, pouca urina (fralda seca > 6–8 h), irritada ou muito sonolenta/"mole", pele que demora a voltar → levar ao PS para hidratação','Vômitos repetidos que impedem de beber, vômito verde (bilioso) ou com sangue, recusa total de líquidos','Sangue ou muco nas fezes, febre alta persistente (≥ 39 °C), dor abdominal intensa ou contínua, barriga inchada/dura, choro intenso em crises com palidez e fezes "em geleia" (intussuscepção)','Diarreia > 7 dias, menor de 3 meses, prematuro, desnutrido, > 8–10 evacuações líquidas/dia, palidez/olheiras/roxos/pouca urina após diarreia com sangue (SHU), convulsão'],ref:'OMS/UNICEF — The Treatment of Diarrhoea 2005 e Zinc 2004; MS — Manejo do Paciente com Diarreia (AIDPI) 2010/2024; SBP — Diarreia Aguda: Diagnóstico e Tratamento 2017; ESPGHAN/ESPID 2014 (Guarino); AAP 1996/CDC 2003 (MMWR); Cochrane 2011 (ondansetrona — Fedorowicz), 2016 (zinco — Lazzerini), 2020 (probióticos — Collinson), 2006 (SRO osmolaridade reduzida — Hahn); Freedman NEJM 2018 (probióticos sem benefício); NICE CG84 2009.'},
{n:'Constipação intestinal funcional (criança)',cid:'K59.0',sp:'Gastroenterologia pediátrica',ps:[{v:'VO / RETAL',i:['Roma IV (≥ 2 critérios por ≥ 1 mês): ≤ 2 evacuações/semana, retenção/postura retentiva, fezes duras/dolorosas, fezes grandes que entopem o vaso, massa fecal palpável, escape fecal (≥ 1×/sem após treino) — 95% funcional; exame: abdome (fecaloma), inspeção anal (fissura, posição do ânus, reflexo cremastérico/anal), coluna lombossacra (fosseta/tufo), crescimento; toque retal NÃO é rotina (só se dúvida/alarme)','ALARME (orgânica — Hirschsprung, hipotireoidismo, APLV, doença celíaca, medular, FC): início < 1 mês de vida/eliminação de mecônio > 48 h, déficit de crescimento, distensão importante, vômitos biliosos, sangue sem fissura, febre, fraqueza de MMII/bexiga neurogênica, ânus anormal/ectópico, ampola vazia com saída explosiva ao toque, fístula/doença perianal → investigar','FECALOMA/IMPACTAÇÃO (massa abdominal/retal, escape fecal): DESIMPACTAÇÃO ORAL é 1ª escolha (igual eficácia e menos trauma que enema): PEG 3350/4000 1–1,5 g/kg/dia = {{d;1500;1000;100000;g}} g/dia ÷ 2 doses por 3–6 dias (até fezes líquidas/claras); RETAL se oral não tolerada/falha ou alívio rápido: enema de glicerina 12% {{v;10;500}} (10 mL/kg, máx. 500 mL — solução glicerinada) ou fosfato de sódio (Fleet® enema pediátrico, ≥ 2 anos, 1×/dia máx. 3 dias — NUNCA em < 2 anos/DRC/Hirschsprung: hiperfosfatemia) ou supositório de glicerina (lactentes); evitar enemas de sabão/água (hiponatremia); NÃO fazer lavagem manual sob sedação de rotina','Dor abdominal por constipação: desimpactar; analgesia simples (dipirona {{d;15;25;1000;gotas}}); não antiespasmódico; excluir apendicite/intussuscepção/obstrução (RX só se dúvida)','Após desimpactação → MANUTENÇÃO IMEDIATA por meses (ver casa); orientar que escape fecal é involuntário (não "manha") e que a recaída é comum se parar cedo']}],casa:[{v:'USO ORAL — MANUTENÇÃO (≥ 2–6 meses, até ≥ 1 mês sem sintomas; desmame lento)',i:[['Polietilenoglicol (PEG) 3350 ou 4000 sem eletrólitos (Muvinlax®/Macrogol pó) — 1ª escolha ≥ 6 meses (ESPGHAN/NASPGHAN); superior à lactulose','1–2 caixas/potes','Dar {{d;600;1000;17000;g}} g/dia (0,4–0,8 g/kg/dia — iniciar 0,4 e ajustar) diluído em 100–250 mL de água/suco/leite, 1×/dia (ou dividido) TODOS OS DIAS; ajustar a dose a cada 2–3 dias para fezes pastosas/macias diárias sem dor (↑ se duras, ↓ se líquidas); usar por meses — não parar ao melhorar'],['OU Lactulose 667 mg/mL xarope (< 6 meses ou se PEG indisponível)','1 frasco (120 mL)','Dar {{v;1;30}} (1–2 mL/kg/dia; ajustar) 1×/dia ou dividido em 2 doses, todos os dias (pode causar gases/cólica)'],['OU Óleo mineral (> 2–3 anos, SEM risco de aspiração/refluxo/neuropatia)','1 frasco','Dar {{v;1.5;45}} (1–3 mL/kg/dia) 1×/dia ou dividido, longe das refeições; NÃO em < 2 anos (pneumonia lipoídica)'],['Bisacodil 5 mg (≥ 3–6 anos) ou Sene — resgate se > 2–3 dias sem evacuar apesar do PEG','10 comprimidos','Dar 1 comprimido (5 mg) à noite SOMENTE se não evacuar em 2–3 dias; não usar diariamente por semanas'],['Supositório de glicerina infantil (lactentes) / Enema de glicerina 12% (resgate em fecaloma leve)','6 unidades','Aplicar 1 supositório se > 3 dias sem evacuar com desconforto (máx. 1–2×/semana)']]}],ori:['DESIMPACTAÇÃO primeiro (3–6 dias com dose alta de PEG até fezes líquidas), depois MANUTENÇÃO diária por meses: a dose é a que mantém fezes macias (tipo 4–5 de Bristol) TODO dia sem dor; ajustar sozinho; não ter medo de "viciar" — PEG não é absorvido nem causa dependência','TREINO DE TOALETE (sem punição): sentar no vaso/penico 5–10 min, 20–30 min APÓS as refeições (reflexo gastrocólico), 2–3×/dia, com os PÉS APOIADOS (banquinho) e joelhos acima do quadril; diário de evacuações com recompensa (adesivos); nunca iniciar desfralde durante a constipação (adiar até resolver); escape fecal não é de propósito','DIETA: fibras conforme idade (frutas com bagaço — mamão, ameixa, laranja, manga; verduras; feijão; aveia; pão integral), água (1–1,5 L/dia em escolares), reduzir leite de vaca em excesso (> 500–700 mL/dia) e ultraprocessados; a dieta sozinha raramente resolve — não atrasar o laxante; atividade física; em lactente < 6 m em aleitamento: evacuar a cada vários dias com fezes macias é NORMAL (não é constipação)','Fissura anal (dor/sangue vivo nas fezes): fezes macias + pomada de óxido de zinco ou hidrocortisona 1%/lidocaína por 7 dias; banho de assento morno','Retorno em 2–4 semanas para ajustar a dose, depois a cada 1–3 meses; suspender só após ≥ 1–2 meses sem sintomas com fezes diárias macias, reduzindo a dose lentamente; recaída → retomar dose cheia; encaminhar ao gastro pediátrico se falha após 3–6 meses de tratamento bem feito ou sinais de alarme'],al:['Vômitos verdes (biliosos), barriga muito inchada e dolorosa, parou de eliminar gases/fezes (obstrução)','Sangue nas fezes em quantidade ou escuro (sem fissura visível), perda de peso/não ganha peso, febre, dor abdominal intensa/persistente','Fraqueza nas pernas, perda de urina/alteração ao urinar, mancha/tufo de pelo na coluna lombar','Lactente < 1 mês com constipação ou que demorou > 48 h para eliminar o mecônio; distensão abdominal com vômitos no recém-nascido (Hirschsprung)','Sem melhora após 2 semanas de PEG em dose adequada ou piora do escape fecal'],ref:'ESPGHAN/NASPGHAN Guideline — Functional Constipation in Infants and Children 2014 (Tabbers) e atualização 2023; Roma IV (Hyams 2016; Benninga 2016); SBP — Constipação Intestinal na Criança 2016/2021; Cochrane 2016 (PEG × lactulose/outros — Gordon); NICE CG99 (2010/2017); Bekkali Pediatrics 2009 (desimpactação oral × retal); AAP.'},
{n:'Refluxo / regurgitação do lactente e cólica do lactente',cid:'K21.9 / R10.4',sp:'Gastroenterologia pediátrica',ps:[{v:'ORIENTAÇÃO',i:['REGURGITAÇÃO FISIOLÓGICA ("golfada"): > 50% dos lactentes aos 4 meses, sem esforço, criança feliz ("happy spitter"), ganhando peso → NÃO é doença, NÃO precisa de exames nem medicamentos; resolve até 12–18 meses','Sinais de DRGE (doença)/alarme: déficit de ganho ponderal, recusa alimentar/choro ao mamar, irritabilidade excessiva com arqueamento (Sandifer), vômitos em jato/biliosos/com sangue, hematêmese/melena, anemia, tosse crônica/sibilância/pneumonia de repetição, apneia/ALTE-BRUE, início > 6 meses ou persistência > 12–18 meses, distensão, febre, fontanela abaulada, macro/microcefalia, hepatoesplenomegalia → investigar (estenose hipertrófica do piloro em 2–8 semanas: vômitos em jato progressivos + fome + oliva palpável → USG; APLV; infecção urinária; HIC; metabólica)','MEDIDAS para regurgitação incômoda: evitar superalimentação (volumes menores e mais frequentes), arrotar durante/após, manter em pé/colo 20–30 min após mamar, evitar fumaça, não apertar fralda; espessamento da fórmula (fórmula AR ou 1 colher de chá de amido de arroz/milho por 30 mL) reduz episódios visíveis em bebês de FÓRMULA; em aleitamento materno exclusivo: manter, revisar pega/técnica; posição: SEMPRE dormir de barriga para cima (elevar a cabeceira do berço não tem evidência e a posição prona/lateral ↑ morte súbita)','Suspeita de APLV (regurgitação + eczema/sangue nas fezes/diarreia/choro intenso): teste terapêutico de exclusão de leite de vaca na dieta da MÃE (se aleitamento) ou fórmula extensamente hidrolisada por 2–4 semanas → reintroduzir para confirmar','MEDICAMENTOS: IBP (omeprazol 1 mg/kg/dia) e antagonistas H2 NÃO são indicados para regurgitação/choro/irritabilidade sem esofagite comprovada (sem benefício em ensaios; ↑ infecções respiratórias/GI, fratura, alergia) — reservar para esofagite erosiva/DRGE confirmada por gastro pediátrico; procinéticos (domperidona/metoclopramida/bromoprida) contraindicados (QT longo/extrapiramidal, sem eficácia); simeticona não age no refluxo','CÓLICA DO LACTENTE (Roma IV: choro/irritabilidade recorrente e prolongada sem causa, < 5 meses, sem déficit ponderal/febre/doença): benigna, pico às 6 semanas, resolve aos 3–4 meses; excluir: fome, calor/frio, fralda, otite, ITU, hérnia encarcerada, torção testicular, torniquete de cabelo em dedo, abrasão de córnea, fratura/maus-tratos (síndrome do bebê sacudido — orientar os pais a NUNCA sacudir; colocar o bebê em local seguro e sair por alguns minutos se exaustos)','Cólica — intervenções com alguma evidência: Lactobacillus reuteri DSM 17938 (5 gotas/dia = 10⁸ UFC) em bebês em ALEITAMENTO MATERNO exclusivo (meta-análise de dados individuais Sung 2018 — ↓ ~50 min de choro/dia; não comprovado em fórmula); exclusão de leite de vaca na dieta materna por 2 semanas se suspeita de APLV; SEM evidência/não recomendados: simeticona (= placebo), chás (erva-doce/camomila — risco de contaminação/botulismo com mel, hiponatremia), "água de gripe"/gripe water, homeopatia, dimeticona, anticolinérgicos (diciclomina — apneia), lactase, massagem/quiropraxia (sem benefício consistente; quiropraxia tem risco)']}],casa:[{v:'ORIENTAÇÕES / USO ORAL',i:[['Lactobacillus reuteri DSM 17938 gotas (Colikids®/BioGaia®) — cólica em aleitamento materno exclusivo (opcional)','1 frasco','Dar 5 gotas 1×/dia por 21–28 dias (no dedo limpo ou colher, não na mamadeira quente)'],['Fórmula infantil antirregurgitação (AR) — se em fórmula, regurgitação volumosa e incômoda, após excluir superalimentação','—','Substituir a fórmula habitual pela versão AR da mesma marca, no mesmo volume; reavaliar em 2 semanas'],['Fórmula extensamente hidrolisada (ou dieta materna sem leite de vaca e derivados por 2–4 semanas) — se suspeita de alergia à proteína do leite de vaca','—','Teste de exclusão por 2–4 semanas com reavaliação; se melhora, reintrodução supervisionada para confirmar'],['Nenhum medicamento (omeprazol, domperidona, simeticona, chás) está indicado para refluxo fisiológico ou cólica — orientação escrita aos pais','—','—']]}],ori:['REFLUXO: golfar sem esforço, feliz e ganhando peso é NORMAL — melhora quando senta (6–7 m) e some até 12–18 m; mamadas menores e mais frequentes, arroto, manter no colo em pé 20–30 min após; não apertar a barriga; NÃO engrossar o leite materno; se fórmula: AR ou engrossar com amido; NÃO usar travesseiro/inclinação/dormir de lado ou de bruços (risco de morte súbita) — sempre de barriga para cima, no berço, sem objetos','CÓLICA: é fase (pico 6 semanas, fim aos 3–4 meses), não é culpa dos pais nem "leite fraco"; técnicas de acalmar (5 S — enrolar/charutinho, posição de lado/bruços no colo, "shhh" ou ruído branco, balanço suave, sucção), banho morno, massagem na barriga, carregar no sling, reduzir estímulos ao fim do dia, revezar entre cuidadores; se o choro se tornar insuportável: colocar o bebê em local seguro (berço) e sair 5–10 min para se acalmar — NUNCA SACUDIR o bebê (lesão cerebral grave); pedir ajuda','Aleitamento: manter livre demanda; mãe não precisa restringir alimentos de rotina (só em teste de APLV por 2 semanas); evitar cafeína em excesso e tabaco; se fórmula: preparo correto, bico adequado, não superalimentar (lactente em fórmula: ~150 mL/kg/dia)','Cuidar da saúde mental dos pais (exaustão, depressão pós-parto — rastrear/EPDS); rede de apoio; o choro NÃO prejudica o bebê; é esperado chorar até 2–3 h/dia nesse período','Retorno de rotina (puericultura) para acompanhar peso/curva; retorno antecipado se sinais de alarme'],al:['Vômitos em JATO, progressivos, com fome logo após (2–8 semanas de vida — estenose do piloro), vômitos verdes/amarelados (biliosos) ou com sangue, barriga inchada','Não ganha peso/perde peso, recusa mamar, choro intenso ao mamar ou arqueamento constante, sangue nas fezes','Choro inconsolável súbito com palidez/vômitos/fezes em geleia (intussuscepção), bolsa escrotal ou virilha inchada e dolorida (hérnia/torção), dedinho roxo (torniquete de cabelo)','Febre (< 3 meses sempre PS), sonolência/moleza, moleira abaulada, pausas respiratórias/roxo durante a mamada, tosse crônica/chiado/pneumonias, dificuldade para engolir','Pais exaustos com pensamentos de machucar o bebê ou a si → procurar ajuda imediatamente (UBS/CAPS/192/188)'],ref:'NASPGHAN/ESPGHAN Pediatric GERD Guidelines 2018 (Rosen); SBP — Refluxo Gastroesofágico 2017/2021 e Cólica do Lactente 2019; Roma IV (Benninga 2016); NICE NG1 (2015/2019); Sung Pediatrics 2018 (L. reuteri — meta-análise de dados individuais); Cochrane 2019 (intervenções dietéticas na cólica — Gordon) e 2018 (manipulação); Orenstein J Pediatr 2009 (lansoprazol sem benefício); AAP Task Force SIDS 2022; Zeevenhooven 2018.'},
/* ===== URINÁRIO ===== */
{n:'Infecção do trato urinário (criança)',cid:'N39.0 / N10',sp:'Nefrologia pediátrica',ps:[{v:'VO / IM / EV',i:['Suspeitar em lactente/criança com febre sem foco (principal causa bacteriana), irritabilidade, vômitos, recusa alimentar, déficit ponderal; maiores: disúria, urgência, dor lombar/abdominal, enurese nova, hematúria; FEBRE ≥ 38–38,5 °C = tratar como pielonefrite (alta)','COLETA ADEQUADA ANTES do antibiótico (obrigatória): sem controle esfincteriano → cateterismo vesical (≥ 50.000 UFC/mL) ou punção suprapúbica (qualquer crescimento); saco coletor APENAS para triagem (se EAS normal, afasta; se alterado, CONFIRMAR por cateter — 85% falso-positivo); com controle → jato médio após higiene (≥ 100.000 UFC/mL; 50.000 se sintomas + piúria); urina I/EAS (leucócitos esterase + nitrito + piúria ≥ 5/campo ou ≥ 10/µL + bacteriúria em Gram); urocultura SEMPRE; hemograma/PCR/procalcitonina/creatinina/hemocultura se < 3 meses, toxemia, internação','INTERNAR (EV): < 2–3 meses (sepse/bacteremia — ampicilina + gentamicina ou cefotaxima/ceftriaxona se > 28 d), toxemia/sepse, vômitos/desidratação/intolerância oral, imunossupressão, uropatia obstrutiva/anomalia conhecida/rim único, falha ambulatorial 48–72 h, dúvida de adesão; o restante → VO desde o início (igual eficácia a EV — Cochrane/Hoberman 1999)','1ª dose no PS: cefalexina {{d;25;50;500;mL}} VO (ou cefuroxima {{d;15;50;500;mL}} VO) OU ceftriaxona 50–75 mg/kg IM {{d;50;350;1000;mL}} (1 g em 2,8 mL lidocaína 1% ≈ 350 mg/mL) se vômitos, com transição VO em 24–48 h; analgesia/antitérmico: dipirona {{d;15;25;1000;gotas}} ou paracetamol {{d;13;13.3;750;gotas}}','Ajustar pelo antibiograma em 48–72 h (resistência: amoxicilina > 50% e SMX-TMP ~30% para E. coli no Brasil — evitar como empíricos em pielonefrite; nitrofurantoína só em cistite, não atinge parênquima); duração: pielonefrite/febril 7–10 dias (SCOUT: 5 dias não inferior em ≥ 2 a com boa resposta — ainda não padrão); cistite (≥ 2 anos, afebril) 3–5 dias','IMAGEM: USG de rins e vias urinárias em TODA 1ª ITU febril (AAP/SBP; NICE: só < 6 m ou atípica/recorrente) — no PS/internação se grave/sem melhora em 48 h, senão em 2–6 semanas; uretrocistografia miccional (UCM) se USG alterada (hidronefrose, cicatriz, uropatia), ITU recorrente/atípica (não E. coli, sepse, massa, creatinina ↑, não resposta em 48 h), < 6 meses com ITU atípica (NICE) — não de rotina após 1ª ITU típica; DMSA tardio (4–6 meses) em recorrente/UCM alterada','Profilaxia antibiótica NÃO é rotina após 1ª ITU; considerar em RVU grau III–V (RIVUR — ↓ recorrência, não ↓ cicatriz) ou recorrência frequente com uropatia — nefro/uro pediátrica; investigar/tratar CONSTIPAÇÃO e disfunção vesical (causa frequente de recorrência); fimose fisiológica não é indicação cirúrgica (corticoide tópico se recorrente)']}],casa:[{v:'USO ORAL',i:[['Cefalexina suspensão 250 mg/5 mL (50 mg/mL) — 1ª escolha empírica (100 mg/kg/dia)','2 frascos','Dar {{d;25;50;500;mL}} de 6/6 h por 7–10 dias (ITU febril/pielonefrite) ou 3–5 dias (cistite ≥ 2 anos, afebril)'],['OU Cefuroxima 250 mg/5 mL (50 mg/mL) — alternativa/2ª geração (30 mg/kg/dia)','1 frasco','Dar {{d;15;50;500;mL}} de 12/12 h por 7–10 dias'],['OU Amoxicilina + clavulanato 400/57 mg/5 mL (80 mg/mL) — se antibiograma sensível (50 mg/kg/dia de amoxicilina)','1 frasco','Dar {{d;25;80;875;mL}} de 12/12 h por 7–10 dias'],['OU Sulfametoxazol + trimetoprima 200/40 mg/5 mL (8 mg TMP/mL) — APENAS se antibiograma sensível e > 2 meses (8 mg/kg/dia de TMP)','1 frasco','Dar {{d;4;8;160;mL}} de 12/12 h por 7–10 dias (cistite 3 dias)'],['OU Nitrofurantoína 5 mg/mL suspensão — SOMENTE cistite afebril, > 1 mês (5–7 mg/kg/dia; não para pielonefrite)','1 frasco','Dar {{d;1.5;5;100;mL}} de 6/6 h por 5 dias, com alimento'],['OU Ciprofloxacino 250 mg/5 mL (50 mg/mL) — reservado a multirresistente/Pseudomonas com antibiograma (20–30 mg/kg/dia)','1 frasco','Dar {{d;12;50;500;mL}} de 12/12 h por 7–10 dias'],['Dipirona gotas 500 mg/mL (≥ 3 m) ou Paracetamol 200 mg/mL','1 frasco','Dar {{d;15;25;1000;gotas}} (dipirona) ou {{d;13;13.3;750;gotas}} (paracetamol) de 6/6 h se febre/dor']]}],ori:['Febre deve ceder em 48–72 h de antibiótico; RETORNO em 48–72 h com o resultado da urocultura/antibiograma para confirmar o diagnóstico (cultura negativa + sem piúria = não era ITU → suspender) e ajustar o antibiótico; completar todos os dias mesmo melhorando','Dar o antibiótico com seringa, em horários fixos (6/6 h = 4×/dia), guardar na geladeira; vômito até 30 min após a dose → repetir','Hidratação abundante, urinar a cada 2–3 h (não segurar), esvaziar bem a bexiga (sentar com pés apoiados, relaxar, "xixi duplo"), higiene da frente para trás (meninas), trocar fraldas com frequência, evitar banho de espuma/roupas apertadas; TRATAR CONSTIPAÇÃO (principal causa de recorrência) — fezes macias diárias; não forçar prepúcio (fimose fisiológica)','Agendar USG de rins e vias urinárias (1ª ITU febril) e retorno ao pediatra para avaliar necessidade de outros exames (uretrocistografia se USG alterada/recorrência); investigação de refluxo vesicoureteral; urocultura de controle NÃO é necessária se melhora clínica (apenas em nova febre)','Não é necessário profilaxia antibiótica após a 1ª infecção; ITU recorrente (≥ 2 febris ou ≥ 3 totais) → nefrologia/urologia pediátrica'],al:['Febre que persiste > 48–72 h de antibiótico, piora do estado geral, vômitos que impedem o remédio, dor lombar/abdominal intensa, prostração/sonolência, recusa alimentar, pouca urina → PS (pielonefrite complicada/abscesso/obstrução — internar, USG/TC)','Menor de 3 meses com febre ou qualquer sinal de toxemia; convulsão; manchas na pele','Nova febre após o término do antibiótico (recorrência — nova urocultura antes de tratar); jato urinário fraco/gotejante, massa abdominal, PA alta, inchaço'],ref:'AAP Clinical Practice Guideline — UTI in Febrile Infants and Children 2–24 months 2011 (Roberts) e reafirmação 2016; NICE NG224 (2022); SBP/SBN — Infecção do Trato Urinário 2016/2021; EAU/ESPU 2024; Cochrane 2014 (VO × EV — Strohmeier), 2019 (profilaxia — Williams), 2016 (duração curta em cistite); RIVUR NEJM 2014 (Hoberman); SCOUT JAMA Pediatr 2023 (Zaoutis — 5 × 10 dias); Shaikh JAMA Pediatr 2016 (atraso no tratamento e cicatriz).'},
/* ===== PARASITOSES / INFECÇÕES ===== */
{n:'Parasitoses intestinais (oxiúros, áscaris, giárdia, outros)',cid:'B80 / B77 / A07.1 / B82.9',sp:'Infectologia pediátrica',ps:[{v:'VO',i:['Diagnóstico: EPF 3 amostras (dias alternados — MIF/Hoffman/Kato-Katz); fita gomada/swab anal matinal (oxiúros — Graham, 3 dias); antígeno fecal/ELISA para Giardia se disponível; eosinofilia sugere helminto tecidual (estrongiloides, toxocara, ancilóstomo); TRATAMENTO EMPÍRICO (sem EPF) é aceitável em prurido anal noturno típico (oxiúros) e em áreas de alta prevalência (OMS: desparasitação periódica com albendazol 1–2×/ano em pré-escolares/escolares de áreas endêmicas — tratamento em massa)','OXIÚROS (Enterobius — prurido anal/vulvar noturno, vermes brancos de 1 cm nas fezes/períneo): albendazol 400 mg (200 mg se 1–2 anos) dose única, REPETIR em 2 semanas (ovos não são mortos); OU mebendazol 100 mg DU + repetir em 2 sem; OU pamoato de pirvínio 10 mg/kg DU (gestante/< 1 ano) — TRATAR TODOS OS CONTATOS DOMICILIARES simultaneamente (reinfecção)','ÁSCARIS (vermes grandes, dor abdominal, eliminação): albendazol 400 mg DU (≥ 2 a; 1–2 a: 200 mg) ou mebendazol 100 mg 12/12 h 3 d; suboclusão intestinal (massa palpável, vômitos, distensão): jejum, SNG, hidratação, piperazina 75 mg/kg/dia 2 dias ou óleo mineral 2 mL/kg → cirurgia se obstrução completa; ascaridíase biliar: USG','GIÁRDIA (diarreia crônica/intermitente pastosa fétida, distensão, dor, déficit ponderal, má absorção): metronidazol 15 mg/kg/dia ÷ 3 por 5–7 dias OU secnidazol 30 mg/kg DU (máx. 2 g — melhor adesão) OU tinidazol 50 mg/kg DU (máx. 2 g, > 3 a) OU nitazoxanida 7,5 mg/kg 12/12 h 3 d (≥ 1 a); albendazol 400 mg/dia 5 d é alternativa (eficácia um pouco menor); tratar sintomáticos e contatos sintomáticos; higiene/água','ANCILÓSTOMO/NECATOR (anemia ferropriva, hipoproteinemia, "amarelão"): albendazol 400 mg DU (ou 3 dias) ou mebendazol 100 mg 12/12 h 3 d + sulfato ferroso; TRICHURIS: mebendazol 100 mg 12/12 h 3 d ou albendazol 400 mg 3 d; ESTRONGILOIDES (hiperinfecção em imunossuprimido/corticoide — tratar ANTES de corticoide prolongado): ivermectina 200 mcg/kg/dia 2 dias (≥ 15 kg) ou albendazol 400 mg 12/12 h 3 d (menos eficaz); TÊNIA: praziquantel 5–10 mg/kg DU ou niclosamida; HIMENOLEPIS: praziquantel 25 mg/kg DU; AMEBÍASE (E. histolytica — disenteria/abscesso): metronidazol 35–50 mg/kg/dia ÷ 3 por 7–10 d + teclozan/etofamida (luminal); E. coli/Endolimax/Blastocystis em assintomático → não tratar','ALBENDAZOL: evitar < 1 ano (OMS permite ≥ 12 m; 12–23 m: 200 mg) e no 1º trimestre de gestação; MEBENDAZOL ≥ 1 ano; IVERMECTINA ≥ 15 kg/5 anos; NITAZOXANIDA ≥ 1 ano; PRAZIQUANTEL ≥ 4 anos (OMS: ≥ 2 a); pirvínio é seguro em qualquer idade; metronidazol: gosto ruim, náuseas, evitar álcool (adolescentes)']}],casa:[{v:'USO ORAL',i:[['Albendazol suspensão 400 mg/10 mL (40 mg/mL) ou comprimido mastigável 400 mg — oxiúros/áscaris/ancilóstomo (≥ 1 ano)','1 frasco (ou 2 comprimidos)','Dar {{p;1–2 anos: 5 mL (200 mg) · ≥ 2 anos: 10 mL (400 mg) ou 1 comprimido}} em dose única, mastigado/com alimento; REPETIR a mesma dose após 14 dias (oxiúros; opcional nos demais). Tratar todos da casa no mesmo dia (oxiúros)'],['OU Mebendazol suspensão 100 mg/5 mL ou comprimido 100 mg (≥ 1 ano)','1 frasco','Dar 5 mL (100 mg) de 12/12 h por 3 dias (áscaris/tricuríase/ancilóstomo); oxiúros: 5 mL dose única e repetir em 14 dias'],['OU Pamoato de pirvínio 10 mg/mL suspensão — oxiúros em < 1 ano/gestante','1 frasco','Dar {{d;10;10;600;mL}} (10 mg/kg, máx. 600 mg) em dose única; repetir em 14 dias (tinge as fezes de vermelho)'],['Metronidazol suspensão 40 mg/mL (200 mg/5 mL) — GIÁRDIA/amebíase','1 frasco','Dar {{d;5;40;250;mL}} de 8/8 h por 5–7 dias (15 mg/kg/dia), após as refeições (amebíase: {{d;12;40;500;mL}} 8/8 h por 7–10 dias)'],['OU Secnidazol 30 mg/mL suspensão — giárdia (dose única, ≥ 1 ano)','1 frasco','Dar {{d;30;30;2000;mL}} (30 mg/kg, máx. 2 g) em dose única após uma refeição'],['OU Nitazoxanida 20 mg/mL (Annita®) — giárdia/cripto/amplo espectro (≥ 1 ano)','1 frasco','Dar {{p;1–3 anos: 5 mL · 4–11 anos: 10 mL · ≥ 12 anos: 25 mL (500 mg)}} de 12/12 h por 3 dias, com alimento (urina alaranjada)'],['Ivermectina 6 mg comprimido — estrongiloidíase/escabiose (≥ 15 kg)','{{p;1 cp para cada 30 kg por dose}}','Dar 200 mcg/kg ({{d;0.2;6;18;cp}}) em dose única, em jejum; estrongiloides: repetir no dia seguinte (2 dias); escabiose: repetir em 7–14 dias'],['Sulfato ferroso gotas 25 mg Fe/mL — se anemia (ancilóstomo/tricuríase)','1 frasco','Dar {{d;3;1.25;60;gotas}} (3 mg/kg/dia de ferro elementar; 1 gota = 1,25 mg Fe) 1×/dia entre as refeições com suco cítrico, por 3 meses após normalizar a hemoglobina']]}],ori:['OXIÚROS: tratar TODA a família no mesmo dia e repetir em 2 semanas; lavar roupas de cama/íntimas/toalhas em água quente e secar ao sol no dia do tratamento (não sacudir — dispersa ovos); banho matinal (retira ovos depositados à noite); unhas curtas e limpas; lavar as mãos após o banheiro/antes de comer; trocar roupa íntima diariamente; aspirar/limpar quarto; o prurido pode ser aliviado com pomada de óxido de zinco; reinfecção é muito comum (ovos sobrevivem 2–3 semanas no ambiente) — não é falha do remédio','HIGIENE GERAL: lavar as mãos com água e sabão (após banheiro, antes das refeições, após brincar na terra/com animais), beber água filtrada/fervida/tratada, lavar bem frutas/verduras (hipoclorito 1 colher de sopa/L por 15 min), cozinhar bem carnes, usar calçados (ancilóstomo/estrongiloides penetram pela pele), saneamento (não defecar no solo), proteger alimentos de moscas; desparasitar cães/gatos','Giárdia: pode haver intolerância à lactose transitória por semanas após (reduzir leite temporariamente); reavaliar peso/crescimento; EPF de controle 2–4 semanas após se sintomas persistirem (resistência ao metronidazol — trocar classe)','Áscaris: pode eliminar vermes pelas fezes/vômito/nariz após o remédio nas primeiras 48 h (normal — não é piora); se dor intensa/vômitos/barriga inchada: PS (suboclusão)','Creche/escola: tratamento periódico (OMS recomenda albendazol a cada 6–12 meses em áreas endêmicas); atualizar vacinas; suplementar ferro/vitamina A conforme idade'],al:['Dor abdominal intensa, vômitos repetidos (verdes), barriga inchada, parou de evacuar (suboclusão por áscaris) → PS','Icterícia (olhos amarelos), dor no fígado, febre alta (ascaridíase biliar/abscesso amebiano)','Diarreia com sangue, febre e toxemia (amebíase invasiva/shigelose), palidez intensa, cansaço (anemia grave), inchaço de pernas/barriga (hipoproteinemia), perda de peso/não ganha peso','Tosse com chiado/falta de ar 1–2 semanas após (síndrome de Löffler — migração larvária), urticária persistente, prurido/lesão serpiginosa na pele que "anda" (larva migrans), convulsão/cefaleia (neurocisticercose — tênia)','Vômitos/diarreia/dor com uso de corticoide ou imunossuprimido (estrongiloidíase disseminada — grave)'],ref:'OMS — Preventive Chemotherapy / Soil-transmitted helminthiases 2017 e Guideline 2017; MS — Guia de Vigilância em Saúde 2024 (Geo-helmintíases; Giardíase); SBP — Parasitoses Intestinais 2020 (Departamento de Gastroenterologia); Cochrane 2012 (giardíase — Granados) e 2020 (albendazol/mebendazol — Welch); CDC Parasites — Treatment 2023; Keiser & Utzinger JAMA 2008 (eficácia dos anti-helmínticos); IDSA 2017 (diarreia infecciosa).'},
{n:'Varicela (catapora)',cid:'B01.9',sp:'Infectologia pediátrica',ps:[{v:'VO',i:['Diagnóstico clínico: febre + exantema pruriginoso polimórfico (mácula → pápula → vesícula "gota de orvalho" → crosta) em VÁRIOS ESTÁGIOS simultâneos, centrípeto (tronco/couro cabeludo/mucosas), surtos por 3–5 dias; contagiosa de 1–2 dias ANTES do rash até todas as lesões em crosta (~5–7 dias); incubação 10–21 dias; notificação (casos graves/óbitos; surtos)','ACICLOVIR VO — NÃO é rotina em criança saudável < 12 anos (benefício discreto: ↓ 1 dia de febre/lesões se iniciado ≤ 24 h — AAP); INDICADO (iniciar ≤ 24–72 h do rash): ≥ 12–13 anos (adolescentes/adultos — doença mais grave), 2º caso no domicílio (inóculo maior), doença cutânea/pulmonar crônica (eczema grave, FC, asma), uso de corticoide inalado/sistêmico ou salicilato crônico, imunossupressão leve: aciclovir 20 mg/kg/dose (máx. 800 mg) 4×/dia (6/6 h, acordado) por 5 dias = {{d;20;40;800;mL}} da suspensão 200 mg/5 mL (40 mg/mL); valaciclovir 20 mg/kg 8/8 h (máx. 1 g) ≥ 2 a é alternativa (melhor biodisponibilidade)','ACICLOVIR EV 10 mg/kg 8/8 h (500 mg/m² em imunossuprimidos) 7–10 d + INTERNAR: imunossuprimido (quimioterapia, HIV, transplante, corticoide alto), RN (mãe com varicela 5 dias antes a 2 dias após o parto — + VZIG), varicela disseminada/hemorrágica, pneumonia, encefalite (ataxia cerebelar isolada é benigna), hepatite, celulite/fasciíte necrosante (GAS — + clindamicina + oxacilina/cefazolina), gestante com pneumonia','SINTOMÁTICOS: dipirona {{d;15;25;1000;gotas}} ou paracetamol {{d;13;13.3;750;gotas}} — NUNCA AAS (síndrome de Reye); EVITAR ibuprofeno/AINE (associação com fasciíte necrosante/infecção invasiva por GAS — Lesko 2001; evidência observacional, mas recomendação SBP/NICE); prurido: anti-H1 oral (dexclorfeniramina/hidroxizina à noite; cetirizina/loratadina de dia), banhos frios com aveia/permanganato 1:40.000, loção de calamina; infecção bacteriana secundária (impetiginização, celulite — lesão com eritema > 1–2 cm, pus, febre nova após o 3º–4º dia): cefalexina {{d;12.5;50;500;mL}} 6/6 h 7 d (ou amoxicilina-clavulanato); não usar talco/pomadas','PROFILAXIA PÓS-EXPOSIÇÃO (contato domiciliar/face a face > 5 min/sala > 1 h): VACINA varicela até 5 dias (ideal 3) em suscetíveis ≥ 9 meses imunocompetentes (bloqueio de surto — PNI a partir de 9 m em creches/hospitais); IMUNOGLOBULINA ANTI-VARICELA-ZÓSTER (VZIG/IGHAVZ — CRIE) 125 UI/10 kg (máx. 625) IM até 96 h (ideal) a 10 dias: imunossuprimidos, gestantes suscetíveis, RN de mãe com varicela periparto, prematuros < 28 sem ou < 1 kg (qualquer história materna) ou ≥ 28 sem de mãe suscetível internados; ACICLOVIR profilático 20 mg/kg 4×/d do 7º ao 14º dia pós-exposição se VZIG indisponível/não elegível','GESTANTE suscetível exposta: sorologia IgG urgente → VZIG ≤ 96 h–10 d se negativa; varicela na gestação: aciclovir VO (≥ 20 sem; EV se pneumonia) — referência ao pré-natal de alto risco (síndrome da varicela congênita < 20 sem: 1–2%)']}],casa:[{v:'USO ORAL',i:[['Aciclovir suspensão 200 mg/5 mL (40 mg/mL) ou comprimido 200/400 mg — SOMENTE se indicação (≥ 12 anos, 2º caso na casa, doença crônica, corticoide/salicilato), início ≤ 24–72 h','1–2 frascos (200 mL)','Dar {{d;20;40;800;mL}} (20 mg/kg, máx. 800 mg) 4×/dia (ao acordar, almoço, jantar e ao dormir — 6/6 h) por 5 dias; beber bastante água'],['Dipirona gotas 500 mg/mL (≥ 3 m) OU Paracetamol gotas 200 mg/mL — NUNCA AAS; EVITAR ibuprofeno','1 frasco','Dar {{d;15;25;1000;gotas}} (dipirona) ou {{d;13;13.3;750;gotas}} (paracetamol) de 6/6 h se febre ou dor'],['Dexclorfeniramina xarope 0,4 mg/mL (2 mg/5 mL) (≥ 2 anos) — prurido (sedativo, útil à noite)','1 frasco','Dar {{d;0.05;0.4;2;mL}} (0,05 mg/kg) de 8/8 h, principalmente à noite, se coceira; máx. 5 dias'],['OU Hidroxizina xarope 2 mg/mL (≥ 6 meses) — prurido/noite','1 frasco','Dar {{d;0.5;2;25;mL}} (0,5 mg/kg) de 8/8 h se coceira intensa (sonolência)'],['OU Cetirizina solução 1 mg/mL (≥ 6 meses) / Loratadina xarope 1 mg/mL (≥ 2 anos) — não sedativo (dia)','1 frasco','Cetirizina: 6 m–2 a: 2,5 mL 1×/dia; 2–6 a: 2,5 mL 12/12 h; > 6 a: 5–10 mL 1×/dia. Loratadina: < 30 kg: 5 mL 1×/dia; ≥ 30 kg: 10 mL 1×/dia'],['Cefalexina suspensão 250 mg/5 mL — APENAS se infecção bacteriana das lesões (pus, vermelhidão/calor ao redor, febre nova)','1 frasco','Dar {{d;12.5;50;500;mL}} de 6/6 h por 7 dias (50 mg/kg/dia)']]},{v:'USO TÓPICO',i:[['Loção de calamina (ou pasta d\'água) / banho com aveia coloidal ou permanganato de potássio 1:40.000 (1 comprimido de 100 mg em 4 L de água)','1 frasco','Aplicar a loção nas lesões 3–4×/dia; banhos mornos/frios rápidos 2–3×/dia; secar sem esfregar; NÃO usar talco, pomadas antibióticas, álcool ou "receitas caseiras"'],['Antisséptico (clorexidina 2% degermante ou sabonete neutro) — higiene das lesões','1 frasco','Usar no banho diário; unhas curtas e limpas (luvas/meias nas mãos de lactentes à noite)']]}],ori:['ISOLAMENTO: afastar da escola/creche até TODAS as lesões estarem em crosta (geralmente 5–7 dias após o início do rash); evitar contato com gestantes, recém-nascidos, imunossuprimidos (quimioterapia/transplante/corticoide alto) e adultos que nunca tiveram varicela — avisar escola/contatos (vacina de bloqueio até 5 dias para quem nunca teve/não vacinado ≥ 9 meses)','NÃO coçar (cicatrizes e infecção): unhas curtas, roupas leves de algodão, banhos frios/aveia, loção de calamina, anti-histamínico; não estourar as bolhas; não usar talco/pomadas; trocar roupas de cama diariamente','NUNCA dar AAS/aspirina (síndrome de Reye) e EVITAR ibuprofeno/anti-inflamatórios (risco de infecção grave de pele); febre: só dipirona ou paracetamol; alimentação leve/fria se lesões na boca; hidratação','Febre dura 2–4 dias; lesões novas param de surgir em 3–5 dias; crostas caem em 1–2 semanas (manchas claras/escuras temporárias; cicatriz se infectar/coçar); a criança pode ter varicela leve mesmo vacinada (poucas lesões)','VACINA: contatos suscetíveis ≥ 9 m–12 m (bloqueio) e esquema de rotina (15 m tetraviral + 4 a); quem teve varicela não precisa vacinar; a doença confere imunidade (zóster pode ocorrer anos depois); irmãos que ainda não adoeceram: aciclovir profilático não é rotina em saudáveis (podem receber vacina até 5 dias ou tratar precocemente se adoecerem)'],al:['Febre que VOLTA ou persiste após o 4º dia, lesão com vermelhidão que se espalha, calor, pus, dor intensa desproporcional, mancha roxa/escura que cresce rapidamente (celulite/fasciíte necrosante — EMERGÊNCIA)','Dificuldade para respirar, tosse intensa, dor no peito (pneumonia — adolescentes/gestantes)','Sonolência excessiva, confusão, vômitos repetidos, dor de cabeça forte, convulsão, rigidez de nuca (encefalite); desequilíbrio para andar (ataxia cerebelar — avaliar, geralmente benigna)','Sangramento nas lesões/gengiva/manchas roxas (varicela hemorrágica), olhos amarelos, dor abdominal intensa, recusa total de líquidos, lesões nos olhos com dor/vermelhidão','Qualquer sintoma em bebê < 1 mês, imunossuprimido ou gestante da casa que teve contato'],ref:'AAP Red Book 2024 (Varicella-Zoster); CDC — Varicella Clinical Overview / ACIP 2007; SBP — Varicela 2019 e Calendário 2024; MS — Guia de Vigilância em Saúde 2024 e Manual dos CRIE 2023 (IGHAVZ; vacina de bloqueio ≥ 9 m); Cochrane 2005 (aciclovir — Klassen); Lesko Pediatrics 2001 (ibuprofeno e fasciíte); NICE CKS Chickenpox 2023; Dunkle NEJM 1991 (aciclovir em crianças saudáveis).'},
{n:'Doença mão-pé-boca / estomatite herpética / aftas',cid:'B08.4 / B00.2 / K12.0',sp:'Infectologia pediátrica',ps:[{v:'VO / TÓPICO',i:['MÃO-PÉ-BOCA (Coxsackie A16/A6, EV71 — 1–5 anos, creche, verão/outono): febre baixa 1–2 d → vesículas/úlceras em boca (língua, mucosa jugal, palato — poupam gengiva) + pápulas/vesículas em mãos, pés, nádegas, joelhos (A6: lesões extensas/atípicas, descamação e onicomadese semanas depois); contágio por saliva/fezes/vesículas por 1–2 semanas (fezes semanas); tratamento SINTOMÁTICO; autolimitada em 7–10 dias','GENGIVOESTOMATITE HERPÉTICA (HSV-1 primária, 6 m–5 a): febre alta 2–3 d, GENGIVA edemaciada/sangrante + úlceras em toda a boca (inclusive lábios/perioral), sialorreia, halitose, adenopatia, recusa alimentar/desidratação (principal complicação); dura 10–14 d; ACICLOVIR VO 15 mg/kg/dose (máx. 200 mg) 5×/dia por 7 dias SE iniciado ≤ 72–96 h do início (↓ duração das lesões em ~4 d, febre, excreção viral — Amir BMJ 1997; Cochrane 2008) = {{d;15;40;200;mL}} da suspensão 200 mg/5 mL; internar se desidratação grave/recusa total (aciclovir EV, hidratação), imunossuprimido, eczema herpético (Kaposi varioliforme — eczema atópico + disseminação: aciclovir EV)','AFTAS (estomatite aftosa recorrente — minor): úlceras rasas < 1 cm, amareladas com halo eritematoso, em mucosa NÃO queratinizada (lábio interno, jugal, soalho), sem febre/sem lesões de pele, recorrentes; sintomático; investigar se frequentes/grandes: deficiência de ferro/B12/folato/zinco, doença celíaca, DII (Crohn), PFAPA (febre periódica + aftas + faringite + adenite a cada 3–6 semanas, 1–5 anos — prednisona 1–2 mg/kg dose única aborta a crise), Behçet, neutropenia cíclica, HIV; herpangina (Coxsackie: úlceras só em palato mole/pilares + febre alta)','ANALGESIA é o tratamento central (permite hidratar): dipirona {{d;15;25;1000;gotas}} ou paracetamol {{d;13;13.3;750;gotas}} em HORÁRIO FIXO nos primeiros dias (não "se dor"); ibuprofeno {{d;10;5;400;gotas}} (≥ 6 m, hidratado) pode ser superior para dor oral; dar 30 min ANTES das refeições; tópicos: lidocaína 2% gel em pequena quantidade com cotonete nas úlceras maiores antes de comer (≥ 2–3 a; máx. 3 mg/kg/dose — risco de convulsão/aspiração em excesso; AAP desaconselha lidocaína viscosa de rotina em lactentes), "magic mouthwash" (difenidramina + hidróxido de alumínio/Mg 1:1 — bochechar/cuspir em maiores ou aplicar com cotonete) — evidência fraca; benzidamina spray/colutório (≥ 6 a); triancinolona 0,1% em orabase nas aftas (não em herpes)','HIDRATAÇÃO: líquidos frios/gelados (água, leite, iogurte, picolé de fruta/SRO congelado, água de coco, gelatina), evitar ácidos/salgados/quentes/duros; copo/colher/seringa se recusa a mamadeira; se não urina em 8–12 h, sem lágrimas, letárgica → SRO/EV no PS (plano B/C)','NÃO prescrever: antibiótico (viral), aciclovir tópico (ineficaz), corticoide em herpes (dissemina), nistatina (não é candidíase — exceto placas brancas removíveis em lactente), antissépticos com álcool, violeta de genciana, mel em < 1 ano']}],casa:[{v:'USO ORAL',i:[['Dipirona gotas 500 mg/mL (≥ 3 m) OU Paracetamol gotas 200 mg/mL — em HORÁRIO FIXO nos primeiros 2–3 dias','1 frasco','Dar {{d;15;25;1000;gotas}} (dipirona) ou {{d;13;13.3;750;gotas}} (paracetamol) de 6/6 h, 30 min antes das principais refeições, mesmo sem febre, por 2–3 dias; depois se dor'],['Ibuprofeno gotas 100 mg/mL (≥ 6 meses, se bem hidratada) — alternar/associar se dor intensa','1 frasco','Dar {{d;10;5;400;gotas}} de 8/8 h por 2–3 dias, após alimentação/líquidos'],['Aciclovir suspensão 200 mg/5 mL (40 mg/mL) — APENAS gengivoestomatite herpética com ≤ 72–96 h de início','1 frasco (200 mL)','Dar {{d;15;40;200;mL}} (15 mg/kg, máx. 200 mg = 5 mL) 5×/dia (a cada 4 h enquanto acordada: ex. 7-11-15-19-23 h) por 7 dias'],['Soro de reidratação oral (congelar em forminhas de picolé)','3 envelopes','Oferecer picolés de SRO/líquidos gelados várias vezes ao dia; meta: urinar pelo menos a cada 6–8 h']]},{v:'USO TÓPICO (bucal)',i:[['Lidocaína 2% gel (Xylocaína® geleia) — ≥ 2–3 anos, úlceras muito dolorosas, com moderação','1 bisnaga','Aplicar uma quantidade do tamanho de uma ervilha, com cotonete, SOMENTE nas úlceras maiores, 20–30 min antes das refeições, no máximo 4×/dia (não espalhar na boca toda; não deixar engolir em quantidade; não usar em lactentes)'],['Triancinolona acetonida 0,1% em orabase (Omcilon-A Orabase®) — APENAS aftas (não em herpes/mão-pé-boca)','1 bisnaga','Aplicar fina camada sobre a afta (sem esfregar) 2–3×/dia após as refeições e ao dormir, por até 5–7 dias'],['Bochecho com água morna e sal (½ colher de chá em 1 copo) ou bicarbonato (≥ 4–5 anos que sabem cuspir) / limpeza suave da boca com gaze úmida em lactentes','—','2–3×/dia após as refeições; escova macia; evitar enxaguantes com álcool']]}],ori:['MÃO-PÉ-BOCA: dura 7–10 dias; isolamento da creche enquanto febre e lesões na boca ativas/babando (geralmente 5–7 dias) — as fezes contaminam por semanas: lavar as mãos sempre após fralda/banheiro, lavar brinquedos, não compartilhar talheres/copos/chupetas; as unhas podem descolar e as mãos/pés descamar 1–2 meses depois (normal, voltam a crescer); pode pegar de novo (outros vírus)','ESTOMATITE HERPÉTICA: contagiosa por saliva (beijo, chupeta, talheres) até as lesões cicatrizarem (10–14 d); afastar da creche enquanto babando/febre; manter longe de recém-nascidos, gestantes com lesões ativas, imunossuprimidos e crianças com dermatite atópica (eczema herpético grave); lavar as mãos (herpes no olho/dedo — panarício herpético: não deixar chupar o dedo); o vírus fica latente — herpes labial recorrente no futuro (sol, febre, estresse)','AFTAS: evitar alimentos ácidos/duros/apimentados e pasta de dente com lauril sulfato de sódio (SLS); dieta variada (ferro, B12, folato, zinco); duram 7–14 dias; se > 3–4 episódios/ano, muito grandes, com febre periódica, dor articular, lesões genitais/oculares, diarreia/perda de peso → investigar com o pediatra (hemograma, ferritina, B12, folato, antitransglutaminase)','ALIMENTAÇÃO: o importante é LÍQUIDO (não a comida sólida — pode ficar 3–5 dias comendo pouco); gelados aliviam (picolé, iogurte, vitamina, gelatina, sopa fria, mingau frio); oferecer no copo/colher/seringa; dar o analgésico 30 min antes; evitar suco de laranja/limão/tomate, salgados, biscoito, quente','Escovar os dentes suavemente (escova macia/gaze) mesmo com dor — previne infecção secundária e halitose'],al:['Sinais de DESIDRATAÇÃO: urina escassa (> 8–12 h sem urinar/fralda seca), boca seca, sem lágrimas, olhos fundos, sonolência/irritabilidade intensa, recusa TOTAL de líquidos → PS para hidratação (SRO/soro na veia)','Febre > 3–4 dias, febre alta persistente ou que volta, prostração, rigidez de nuca, vômitos repetidos, sonolência excessiva, tremores/abalos, dificuldade para andar/fraqueza (mão-pé-boca por EV71: meningite/encefalite/mielite — raro)','Lesões de pele que pioram muito, bolhas grandes, pus, vermelhidão ao redor (infecção secundária); lesões espalhando-se rapidamente em criança com eczema (eczema herpético — EMERGÊNCIA)','Lesão no olho, olho vermelho/dor/lacrimejamento (herpes ocular — oftalmologista urgente); dedo com bolhas dolorosas (panarício herpético)','Falta de ar, palpitações, palidez (miocardite — raríssimo); dificuldade para engolir a própria saliva com babação intensa e voz abafada (diferencial: abscesso/epiglotite)'],ref:'AAP Red Book 2024 (Enterovirus; Herpes Simplex); Amir BMJ 1997 (aciclovir na gengivoestomatite — ECR); Cochrane 2008 (Nasser — aciclovir estomatite herpética); SBP — Estomatites 2019 (Departamento de Infectologia/Odontopediatria); Hopper 2014 (lidocaína viscosa em crianças — alerta FDA 2014); Scully/Porter — RAS 2008; Marshall PFAPA 1987 / Vanoni 2016; Esposito 2018 (HFMD review); MS — Nota Informativa Síndrome Mão-Pé-Boca.'},
/* ===== PELE ===== */
{n:'Dermatite atópica (eczema) — crise',cid:'L20.9',sp:'Dermatologia pediátrica',ps:[{v:'TÓPICO / VO',i:['Prurido intenso + eczema (eritema, pápulas, escoriações, liquenificação) em face/couro cabeludo/extensoras (lactente) → flexuras (criança) + xerose + história pessoal/familiar de atopia; crise = piora com exsudação/crostas ± infecção secundária (S. aureus — crostas melicéricas, pústulas, piora súbita; eczema herpético — vesículas umbilicadas monomórficas, erosões "punched-out", febre, dor → aciclovir EV/VO urgente + oftalmo se periocular)','CORTICOIDE TÓPICO é o tratamento da crise (seguro em cursos curtos; "corticofobia" leva à falha): potência conforme local/gravidade — FACE/dobras/genitais/lactentes: BAIXA (hidrocortisona 1% ou desonida 0,05%) 1–2×/dia por 5–7 dias; TRONCO/membros: MÉDIA (mometasona 0,1% 1×/dia, metilprednisolona aceponato 0,1%, betametasona valerato 0,1%) por 7–14 dias até limpar, depois reduzir (2×/semana nas áreas de recorrência — "terapia proativa"); liquenificação em maiores: potência alta curta; quantidade: unidade da ponta do dedo (0,5 g) cobre 2 palmas de adulto; aplicar SOBRE o hidratante ou 15 min antes; evitar clobetasol em < 12 a e qualquer alta potência em face/dobras','INFECÇÃO SECUNDÁRIA (impetiginização): limitada → mupirocina 2% 8/8 h 5–7 d + corticoide tópico; extensa/febre → cefalexina {{d;12.5;50;500;mL}} VO 6/6 h 7 d (50 mg/kg/dia) ou amoxicilina-clavulanato; banhos com clorexidina 2–4% diluída ou "banho de hipoclorito" (água sanitária 2–2,5%: ½ copo = 120 mL em banheira de 150 L; 2×/sem) ↓ colonização por S. aureus em casos recorrentes','PRURIDO/SONO: anti-H1 sedativo à noite por poucos dias (hidroxizina {{d;0.5;2;25;mL}} 2 mg/mL ou dexclorfeniramina {{d;0.05;0.4;2;mL}}) — não tratam o eczema, só ajudam a dormir; anti-H1 não sedativos não têm benefício no prurido da DA (sem histamina) — evitar de rotina (NICE/AAD); compressas úmidas frias com SF; "wet wrap" (curativo úmido sobre corticoide + hidratante, 2 camadas, por 1–3 dias) em crises graves — muito eficaz','CORTICOIDE SISTÊMICO: EVITAR (rebote intenso ao suspender, efeitos adversos) — só em crise muito grave/extensa como ponte curta (prednisolona 0,5–1 mg/kg 3–5 d) enquanto se otimiza o tópico, com desmame e encaminhamento; nunca repetidamente; betametasona IM de depósito: NÃO','Grave/refratário/> 20–30% SC/impacto no sono e crescimento → dermato/alergista pediátrico: inibidor de calcineurina tópico (tacrolimo 0,03% ≥ 2 a; pimecrolimo 1% ≥ 3 m — face/dobras/manutenção, sem atrofia), fototerapia, dupilumabe (≥ 6 m), JAK; testes alérgicos apenas se história sugestiva (alergia alimentar coexiste em 30% dos graves — NÃO fazer dietas de exclusão empíricas: desnutrição e ↑ risco de alergia IgE); APLV só com reação reprodutível']}],casa:[{v:'USO TÓPICO',i:[['HIDRATANTE (emoliente) sem perfume/corante, rico em lipídios/ceramidas (creme ou pomada; ex.: Cetaphil® DA, CeraVe®, Fisiogel® AI, Bepantol Derma®, ureia 3–5% em < 2 a/10% em maiores — não em pele lesada) — a BASE do tratamento','2–4 potes/mês (250–500 g/semana em crianças maiores)','Aplicar em TODO o corpo pelo menos 2×/dia (sempre em até 3 min após o banho — "soak and seal") e sempre que a pele estiver seca; TODOS OS DIAS, mesmo sem lesões, para sempre; quantidade generosa'],['Hidrocortisona 1% creme (ou Desonida 0,05%) — FACE, pescoço, dobras, área da fralda, genitais, lactentes','1 bisnaga 30 g','Aplicar fina camada nas lesões 2×/dia por 5–7 dias (até a pele ficar lisa/sem coceira); depois parar ou usar 2×/semana nos locais que sempre voltam'],['Mometasona 0,1% creme (ou Metilprednisolona aceponato 0,1% / Betametasona valerato 0,1%) — TRONCO, braços, pernas (≥ 3 m–2 a conforme bula)','1 bisnaga 30 g','Aplicar fina camada nas lesões 1×/dia (mometasona) ou 2×/dia por 7–14 dias até limpar; depois 2×/semana (ex.: sábado e domingo) nas áreas de recorrência por 1–3 meses ("proativo"); aplicar antes do hidratante ou sobre ele após absorver'],['Tacrolimo 0,03% pomada (≥ 2 anos) ou Pimecrolimo 1% creme (≥ 3 meses) — manutenção em FACE/pálpebras/dobras (não causa atrofia)','1 bisnaga','Aplicar fina camada 2×/dia nas lesões leves de face/dobras ou 2–3×/semana como manutenção (ardência inicial nos 1ºs dias é comum); proteger do sol'],['Mupirocina 2% pomada — se crostas amareladas/pus localizados','1 bisnaga','Aplicar nas lesões infectadas 3×/dia por 5–7 dias, antes do corticoide'],['Sabonete/syndet suave sem perfume (pH ácido) ou óleo de banho — banho morno (não quente) de 5–10 min, 1×/dia','1 frasco','Usar pouca quantidade só nas áreas necessárias; não esfregar; secar com toques; hidratante em 3 min']]},{v:'USO ORAL',i:[['Hidroxizina xarope 2 mg/mL (≥ 6 m) — APENAS à noite se o prurido impedir o sono, por poucos dias','1 frasco','Dar {{d;0.5;2;25;mL}} (0,5 mg/kg) ao deitar por 3–7 dias (sonolência)'],['Cefalexina suspensão 250 mg/5 mL — APENAS se infecção extensa (muitas crostas amareladas/pus, febre)','1 frasco','Dar {{d;12.5;50;500;mL}} de 6/6 h por 7 dias']]}],ori:['A pele atópica é SECA e com barreira frágil: HIDRATAR 2×/dia TODOS OS DIAS (inclusive quando "está boa") é o que previne as crises; quantidade: um adulto gasta ~500 g/semana em criança — use bastante; aplicar logo após o banho (3 min) com a pele úmida','BANHO: morno (não quente), curto (5–10 min), 1×/dia, pouco sabonete suave sem perfume (só axilas/genitais/pés), sem bucha, secar com toques; evitar banho de piscina com cloro sem hidratar depois','CORTICOIDE TÓPICO NÃO "afina a pele" se usado como prescrito em cursos curtos — é seguro e necessário; mais perigoso é NÃO tratar (coceira, infecção, sono); usar fina camada, pelo tempo indicado, e depois manutenção 2×/semana; não usar na face o creme do corpo (mais forte); não usar pomadas "milagrosas" com corticoide forte/antifúngico/antibiótico combinados (Trok®, Quadriderm®) sem orientação','GATILHOS: calor/suor (roupas leves de algodão, evitar lã/sintéticos), ressecamento (ar-condicionado/aquecedor — umidificar), sabão em pó/amaciante perfumado (enxágue duplo, sabão neutro), perfumes/colônias/lenços umedecidos com álcool, pelos de animais, ácaros (colchão/travesseiro com capa, lavar roupa de cama a 60 °C), estresse, infecções; não há necessidade de dieta restritiva sem alergia comprovada; manter aleitamento; vacinas normais (vacina varicela importante — eczema herpético)','Unhas curtas/limpas (luvas de algodão à noite em lactentes); coceira: compressa fria/hidratante gelado em vez de coçar; sol moderado ajuda (com hidratante/protetor físico); retorno em 2–4 semanas para ajustar; 60–70% melhoram até a adolescência; dermatologista/alergista se grave, sem resposta, dúvida ou alergia alimentar suspeita'],al:['Lesões com PUS, crostas amareladas espalhadas, febre, dor, vermelhidão quente que se espalha (infecção bacteriana)','Aparecimento rápido de muitas "bolinhas de água" iguais/feridinhas arredondadas em saca-bocado, com febre e mal-estar, em cima do eczema (ECZEMA HERPÉTICO — emergência, ir ao PS no mesmo dia; se perto do olho: oftalmologista)','Piora com corticoide tópico, eczema que não melhora após 2 semanas de tratamento correto, lesões em locais atípicos, descamação de todo o corpo (eritrodermia), déficit de crescimento, infecções repetidas (investigar imunodeficiência/alergia)','Urticária/inchaço/vômitos/falta de ar após alimento (anafilaxia — alergia alimentar associada)'],ref:'AAD Guidelines Atopic Dermatitis 2023 (Davis — tópicos; Sidbury — sistêmicos); EuroGuiDerm/EADV AD Guideline 2022 (Wollenberg); NICE CG57 (2007/2023); SBP/SBD — Consenso Brasileiro de Dermatite Atópica 2019/2023 (ASBAI/SBD); AAP Clinical Report 2014 (Tollefson); Cochrane 2017 (emolientes — van Zuuren), 2022 (corticoide tópico — estratégias; Lax), 2016 (anti-H1 orais sem benefício — Matterne 2019), 2015 (inibidores de calcineurina — Cury Martins); Huang Pediatrics 2009 (banho de hipoclorito); Schmitt 2011 (terapia proativa — meta-análise).'},
{n:'Dermatite da área da fralda / candidíase perineal',cid:'L22 / B37.2',sp:'Dermatologia pediátrica',ps:[{v:'TÓPICO',i:['DERMATITE IRRITATIVA (mais comum): eritema brilhante nas superfícies CONVEXAS (nádegas, coxas, púbis, genitais externos) que POUPA AS DOBRAS; por contato com urina/fezes (diarreia, antibiótico), fricção, oclusão; grave: erosões/úlceras "em saca-bocado" (Jacquet)','CANDIDÍASE (Candida albicans — após > 3 dias de dermatite, antibiótico, diarreia, candidíase oral concomitante): eritema vermelho-vivo "carne viva" que ACOMETE AS DOBRAS, bordas bem delimitadas com descamação e LESÕES-SATÉLITE (pápulas/pústulas) ao redor; pode haver monilíase oral — tratar ambas','OUTROS (quando não melhora em 1–2 semanas/atípico): dermatite seborreica (dobras + couro cabeludo/face, escamas gordurosas, sem prurido — hidrocortisona 1% + antifúngico), dermatite atópica, psoríase (placas bem delimitadas vermelho-escuro, resistente), impetigo bolhoso (bolhas flácidas/erosões com colarete — mupirocina/cefalexina), estreptococcia perianal (eritema perianal vivo bem delimitado + dor/sangue nas fezes — amoxicilina/penicilina 10 d), escabiose (pápulas/nódulos em genitais/axilas, prurido familiar), acrodermatite enteropática (deficiência de zinco — periorificial + acral + alopecia + diarreia), histiocitose de células de Langerhans (pápulas crostosas/purpúricas em dobras + couro cabeludo, resistente — biópsia), abuso sexual (lesões genitais/anais atípicas, DST)','TRATAMENTO BASE (irritativa): "ABCDE" — Air (deixar sem fralda o máximo possível), Barrier (pasta de óxido de zinco ≥ 10–40%/petrolato em camada ESPESSA a cada troca, sem remover tudo a cada troca — só limpar as fezes por cima), Cleansing (água morna + algodão/pano macio ou óleo mineral; sabonete suave só se fezes; evitar lenços umedecidos com álcool/perfume na pele lesada), Diaper (trocar com frequência — a cada 2–3 h e logo após evacuar; fraldas superabsorventes/tamanho certo, não apertar), Education; NÃO usar talco (aspiração/granuloma), amido de milho (alimenta Candida), pomadas com antibiótico (neomicina — sensibilização), corticoides potentes/combinações (Trok-N®/Quadriderm® — atrofia, estrias, Cushing por oclusão)','CANDIDÍASE: antifúngico tópico — NISTATINA 100.000 UI/g creme ou MICONAZOL 2% creme/pomada (ou clotrimazol 1%, cetoconazol 2%) 2–3×/dia (a cada troca) por 7–14 dias (até 3 dias após desaparecer) + pasta de zinco POR CIMA; se candidíase oral associada: nistatina oral 100.000 UI/mL 1 mL (0,5 mL em cada bochecha) 4×/dia 7–14 d; fluconazol oral 6 mg/kg D1 → 3 mg/kg/dia (máx. 7–14 d) só se extensa/refratária/imunossuprimido','INFLAMAÇÃO INTENSA (irritativa grave, não melhora em 3 dias com barreira): HIDROCORTISONA 1% creme (baixa potência) 2×/dia por NO MÁXIMO 3–5 dias, aplicada ANTES do antifúngico/barreira; nunca corticoide médio/alto na fralda (oclusão multiplica a absorção)','Diarreia/antibiótico em curso: reforçar barreira preventivamente; tratar a diarreia (zinco, SRO) e considerar probiótico; dermatite persistente > 2 semanas apesar de tratamento correto → dermatopediatria (biópsia se suspeita de LCH/psoríase/acrodermatite)']}],casa:[{v:'USO TÓPICO',i:[['Pasta/pomada de ÓXIDO DE ZINCO (≥ 10–40%) com vitamina A+D ou petrolato (Hipoglós®, Bepantol Baby®, Dermodex Prevent®, pasta d\'água, ou óxido de zinco 20–40% em vaselina manipulado para casos graves)','1–2 bisnagas/potes','Aplicar camada ESPESSA (como cobertura de bolo — não precisa ficar transparente) em toda a área da fralda a cada troca; nas trocas seguintes, limpar só as fezes e repor por cima sem esfregar para retirar tudo; manter até 1–2 semanas após a cura e sempre em diarreia/antibiótico'],['Nistatina 100.000 UI/g creme OU Miconazol 2% creme (Daktarin®/Vodol®) ou Clotrimazol 1% — SE houver lesões nas dobras + satélites (Candida)','1 bisnaga','Aplicar fina camada nas lesões a cada troca de fralda (3–4×/dia) por 7–14 dias (até 3 dias após desaparecer); DEPOIS aplicar a pasta de zinco por cima'],['Hidrocortisona 1% creme — APENAS se vermelhidão intensa/inflamada, por poucos dias','1 bisnaga 15 g','Aplicar fina camada nas áreas vermelhas 2×/dia por NO MÁXIMO 3–5 dias, antes do antifúngico e da pasta de zinco; não usar outros corticoides/pomadas combinadas'],['Nistatina 100.000 UI/mL suspensão oral — se também houver placas brancas na boca ("sapinho")','1 frasco','Dar 1 mL (0,5 mL em cada lado da boca, esfregando suavemente com o conta-gotas/dedo limpo) 4×/dia após as mamadas, por 7–14 dias (continuar 2–3 dias após sumir); ferver bicos/chupetas; tratar mamilos da mãe (miconazol creme) se dor/fissura'],['Óleo mineral ou água morna + algodão para limpeza (em vez de lenço umedecido com álcool/perfume enquanto lesada)','1 frasco','Limpar suavemente a cada troca; secar com toques (ou secador em ar frio); deixar sem fralda vários períodos ao dia']]}],ori:['TROCAR A FRALDA com frequência (a cada 2–3 h de dia, assim que evacuar, 1× à noite se evacuou); limpar com água morna e algodão/pano macio (ou óleo mineral), sem esfregar; secar bem com toques antes da pomada; deixar o bebê SEM FRALDA o máximo possível (deitado sobre toalha/forro) várias vezes ao dia — o ar é o melhor remédio','BARREIRA: camada grossa de pasta de zinco a cada troca ("quanto mais branco, melhor"); não é necessário retirar toda a pomada em cada troca — só o que estiver sujo; manter por 1–2 semanas após melhorar e usar preventivamente sempre que houver diarreia ou antibiótico','NÃO USAR: talco, amido de milho/maisena, pomadas com antibiótico, corticoides fortes ou combinados (Trok®, Quadriderm®, Novacort® etc.), lenços umedecidos com álcool/perfume na pele machucada, álcool, "receitas caseiras" (fubá, pasta de dente, leite de magnésia)','Fralda do tamanho certo, não apertada; fraldas descartáveis superabsorventes são melhores que pano; se fralda de pano: lavar com sabão neutro, enxaguar bem, sem amaciante, secar ao sol, trocar mais vezes; roupas largas de algodão','Melhora esperada em 2–3 dias com os cuidados; candidíase em 5–7 dias; retorno se não melhorar em 1 semana ou se piorar; lesões recorrentes/atípicas/em outros locais do corpo → pediatra/dermatologista (pode ser outra doença)'],al:['Bolhas, feridas abertas/úlceras, pus, crostas amareladas, sangramento, lesões que se espalham para fora da fralda (corpo/couro cabeludo), febre, irritabilidade intensa, dor ao evacuar/sangue nas fezes (estreptococo perianal), recusa alimentar','Não melhora em 1 semana com tratamento correto ou piora apesar do tratamento (outro diagnóstico: psoríase, histiocitose, acrodermatite — deficiência de zinco, escabiose, alergia de contato à fralda/lenço)','Bebê que não ganha peso, com diarreia crônica, lesões ao redor da boca/olhos e nas mãos/pés + queda de cabelo (acrodermatite enteropática)','Lesões genitais/anais incomuns, verrugas, corrimento, hematomas em locais suspeitos (considerar abuso — notificar/avaliar)'],ref:'AAP — Diaper Dermatitis (Pediatrics in Review 2021; Shin); SBP — Dermatite da Área das Fraldas 2017/2023 (Departamento de Dermatologia); SBD; Blume-Peytavi Pediatr Dermatol 2014 (prevenção/skin care consensus) e 2018; Stamatas Pediatr Dermatol 2014; Bonifaz Curr Fungal Infect Rep 2016 (candidíase da fralda); Hoeger Pediatr Dermatol 2010 (nistatina × miconazol); NICE CKS Nappy rash 2023.'},
{n:'Impetigo (criança)',cid:'L01.0 / L01.1',sp:'Dermatologia pediátrica',ps:[{v:'TÓPICO / VO',i:['NÃO BOLHOSO (70% — S. aureus ± S. pyogenes; 2–5 a): pápula/vesícula → pústula → erosão com CROSTA MELICÉRICA ("cor de mel") em face (perinasal/perioral) e extremidades, pouco sintomática, adenopatia regional; BOLHOSO (S. aureus produtor de toxina esfoliativa — lactentes): bolhas flácidas 1–3 cm, conteúdo claro → turvo, rompem deixando erosão brilhante com colarete descamativo, tronco/dobras/fralda, sem crosta espessa; ECTIMA: úlcera "em saca-bocado" com crosta aderente (estreptococo, pernas, higiene precária) — tratar VO; muito contagioso (contato direto, fômites), autoinoculação; complicação: glomerulonefrite pós-estreptocócica (1–3 semanas; não prevenida pelo antibiótico mas o tratamento reduz transmissão de cepas nefritogênicas), celulite, SSSS (síndrome da pele escaldada — lactente com eritrodermia dolorosa + descolamento/Nikolsky → internar, oxacilina/clindamicina EV)','LIMPEZA: amolecer e remover crostas com compressas mornas de SF 0,9% ou água e sabão (ou clorexidina 2% degermante) 10–15 min, 2–3×/dia antes do tópico — melhora a penetração e reduz contágio','LOCALIZADO (≤ 3–5 lesões / 1 área, sem bolhas extensas, sem febre): ANTIBIÓTICO TÓPICO apenas — MUPIROCINA 2% pomada ou ÁCIDO FUSÍDICO 2% creme 3×/dia por 5–7 dias (igual ou superior ao oral em impetigo limitado — Cochrane 2012, 68 ECR; retapamulina 1% 2×/dia 5 d é alternativa ≥ 9 m); NÃO usar neomicina/bacitracina (sensibilização, menor eficácia); clorexidina/antissépticos isolados são inferiores ao antibiótico tópico','EXTENSO (> 5 lesões, múltiplas áreas, bolhoso disseminado, ectima, febre/adenopatia importante, imunossuprimido, surto em creche/família, falha tópica em 5–7 d, lesões em boca/perineais): ANTIBIÓTICO ORAL 7 dias — CEFALEXINA 25–50 mg/kg/dia ÷ 6/6 h (1ª escolha; {{d;12.5;50;500;mL}} 6/6 h) ou cefadroxila 30 mg/kg/dia 12/12 h; amoxicilina-clavulanato 25–45 mg/kg/dia 12/12 h; alergia: claritromicina 15 mg/kg/dia 12/12 h (resistência do S. aureus a macrolídeos ↑) ou clindamicina 10–30 mg/kg/dia 8/8 h; suspeita de MRSA comunitário (abscessos/furúnculos recorrentes na família, falha de cefalexina, cultura): SMX-TMP 8–12 mg TMP/kg/dia 12/12 h ({{d;5;8;160;mL}} 12/12 h) ou clindamicina — SMX-TMP não cobre bem estreptococo (associar se dúvida); amoxicilina/penicilina isoladas são INADEQUADAS (S. aureus resistente)','Cultura (swab de lesão/pus) se: recorrente, falha, surto, suspeita de MRSA, imunossuprimido; não é rotina; prurido: anti-H1 oral curto (hidroxizina à noite) se impedir o sono; dipirona/paracetamol se dor/febre; não usar corticoide tópico (dissemina)','RECORRÊNCIA (≥ 2–3 episódios): tratar porta de entrada (dermatite atópica, escabiose, pediculose, picadas, rinite — portador nasal); DESCOLONIZAÇÃO de S. aureus do paciente E familiares: mupirocina 2% intranasal 2×/dia por 5 dias + banhos com clorexidina 2–4% por 5–7 dias (ou banho de hipoclorito 2×/semana por 3 meses); lavar roupas/toalhas a quente; unhas curtas']}],casa:[{v:'USO TÓPICO',i:[['Mupirocina 2% pomada (Bactroban®) OU Ácido fusídico 2% creme (Verutex®) — impetigo LOCALIZADO (poucas lesões)','1 bisnaga 15 g','Após amolecer e remover as crostas (compressa morna 10–15 min), aplicar nas lesões 3×/dia por 5–7 dias (até 2 dias após cicatrizar); cobrir com gaze/curativo se possível (↓ contágio/coçar)'],['Clorexidina 2% degermante (Riohex®) ou sabonete antisséptico — limpeza das lesões','1 frasco','Lavar as lesões e as mãos 2×/dia; usar no banho diário; não compartilhar'],['OPCIONAL — SÓ SE IMPETIGO RECORRENTE: Mupirocina 2% pomada NASAL (descolonização de S. aureus do paciente e de todos da casa; não é para as lesões)','1 bisnaga por pessoa','Aplicar pequena quantidade dentro de cada narina (com cotonete) 2×/dia por 5 dias, todos ao mesmo tempo']]},{v:'USO ORAL (impetigo EXTENSO, bolhoso disseminado, ectima, febre, falha do tópico)',i:[['Cefalexina suspensão 250 mg/5 mL (50 mg/mL) — 1ª escolha (50 mg/kg/dia)','1 frasco (100 mL) ou 2','Dar {{d;12.5;50;500;mL}} de 6/6 h por 7 dias (pode ser dado 8/8 h com dose {{d;17;50;500;mL}}); guardar na geladeira, agitar'],['OU Cefadroxila suspensão 250 mg/5 mL (50 mg/mL) — 12/12 h (adesão)','1 frasco','Dar {{d;15;50;500;mL}} de 12/12 h por 7 dias (30 mg/kg/dia)'],['OU Sulfametoxazol + trimetoprima 200/40 mg/5 mL — suspeita de MRSA comunitário/alergia a betalactâmico (> 2 meses)','1 frasco','Dar {{d;5;8;160;mL}} de 12/12 h por 7 dias (10 mg/kg/dia de TMP)'],['OU Claritromicina suspensão 250 mg/5 mL (50 mg/mL) — alergia a penicilina (menor eficácia contra S. aureus)','1 frasco','Dar {{d;7.5;50;500;mL}} de 12/12 h por 7 dias'],['Hidroxizina xarope 2 mg/mL (≥ 6 m) — apenas se prurido atrapalhar o sono','1 frasco','Dar {{d;0.5;2;25;mL}} à noite por até 5 dias'],['Dipirona gotas 500 mg/mL (≥ 3 m) ou Paracetamol gotas 200 mg/mL — se febre/dor','1 frasco','Dar {{d;15;25;1000;gotas}} (dipirona) ou {{d;13;13.3;750;gotas}} (paracetamol) de 6/6 h se necessário']]}],ori:['É MUITO CONTAGIOSO (contato com as feridas, mãos, toalhas, roupas, brinquedos): lavar as mãos com frequência (criança e cuidadores — após tocar nas lesões/pomada), unhas curtas e limpas, não coçar nem arrancar as crostas (autoinoculação e cicatriz), toalha/roupa de cama/roupas individuais trocadas diariamente e lavadas em água quente, secas ao sol; lavar brinquedos; não compartilhar objetos','AFASTAMENTO da creche/escola até 24 h após o início do antibiótico (oral ou tópico) E com as lesões cobertas/secando (Red Book); lesões descobertas em áreas expostas devem ser cobertas com gaze/curativo quando possível','Amolecer as crostas com compressa de água morna/soro por 10–15 min antes de passar a pomada (a pomada não penetra na crosta); lavar as lesões com água e sabão/clorexidina 2×/dia; banho diário; não usar álcool, iodo, "pó", pomadas caseiras','Melhora esperada em 2–3 dias (lesões secam); cicatrização em 7–10 dias, geralmente SEM cicatriz (pode ficar mancha clara/escura temporária); completar o tratamento mesmo melhorando; retorno em 3–5 dias se sem melhora, piora ou novas lesões (trocar para oral/investigar MRSA)','Tratar a causa de base (dermatite atópica, coceira de picadas, sarna, piolho, rinite/"nariz escorrendo") para evitar recorrência; se repete: tratar portador nasal de todos da casa'],al:['Vermelhidão quente/inchaço que se espalha ao redor das lesões, dor intensa, febre, prostração, gânglios dolorosos/grandes (celulite/linfangite)','Bolhas grandes e extensas, pele vermelha e dolorida que descola ao toque/esfregar como queimadura, principalmente em bebês (síndrome da pele escaldada — EMERGÊNCIA)','Urina escura ("coca-cola"/espumosa), inchaço nos olhos/pernas, pressão alta, dor de cabeça ou menos urina 1–3 semanas após (GLOMERULONEFRITE pós-estreptocócica) → PS','Sem melhora em 3–5 dias de tratamento ou lesões que viram feridas profundas (ectima)/abscessos; episódios repetidos (MRSA/portador — cultura)'],ref:'IDSA SSTI Guideline 2014 (Stevens); AAP Red Book 2024 (Staphylococcal/GAS infections; exclusão escolar); Cochrane 2012 (Koning — Interventions for impetigo, 68 ECR: mupirocina/ácido fusídico ≥ orais em limitado); SBP — Piodermites 2019 (Departamento de Dermatologia); SBD; NICE NG153 Impetigo: antimicrobial prescribing 2020; Hartman-Adams AFP 2014; Bowen PLoS One 2015 (global burden); Gelmetti/Bangert 2012 (prevenção de recorrência).'},
{n:'Escabiose e pediculose (criança)',cid:'B86 / B85.0',sp:'Dermatologia pediátrica',ps:[{v:'TÓPICO / VO',i:['ESCABIOSE: prurido intenso NOTURNO + pápulas/escoriações/túneis em espaços interdigitais, punhos, axilas, cintura, nádegas, genitais; em LACTENTES acomete também PALMAS/PLANTAS, FACE, COURO CABELUDO, com vesículas/pústulas e nódulos; contatos com prurido; nódulos escabióticos (axilas/genitais) podem persistir semanas após cura; impetiginização frequente (risco de GNPE em áreas endêmicas)','ESCABIOSE — PERMETRINA 5% loção/creme é 1ª escolha em TODAS as idades ≥ 2 MESES (AAP/CDC/IACS; < 2 meses: enxofre precipitado 5–10% em vaselina 3 noites consecutivas, ou permetrina sob orientação especializada): aplicar à noite do PESCOÇO AOS PÉS (em LACTENTES e < 2 anos INCLUIR COURO CABELUDO, FACE — poupando olhos/boca — pescoço, atrás das orelhas), todas as dobras, entre dedos, sob as unhas, umbigo, genitais; deixar 8–14 h, enxaguar pela manhã; REPETIR em 7 dias (ovos); tratar TODOS os contatos domiciliares/íntimos SIMULTANEAMENTE (mesmo sem sintomas); IVERMECTINA VO 200 mcg/kg DU + repetir em 7–14 d — alternativa em ≥ 15 kg (e ≥ 5 anos pela bula; estudos sugerem segurança em menores — uso off-label com cautela), útil em surtos/institucionais/difícil adesão/sarna crostosa (associar à permetrina); CONTRAINDICADA < 15 kg, gestantes (permetrina é segura na gestação/lactação); benzoato de benzila 25% (diluir ½ em crianças) é irritante — 2ª linha; lindano: proibido; monossulfiram/tiabendazol: não','SARNA CROSTOSA (norueguesa — imunossuprimidos, síndrome de Down, institucionalizados; crostas espessas/hiperqueratose, pouco prurido, milhares de ácaros, surtos): permetrina diária por 7 dias (depois 2×/sem até cura) + ivermectina dias 1, 2, 8, 9, 15 (+ 22, 29 se grave) + queratolíticos; isolamento de contato; internação','PRURIDO PÓS-ESCABIÓTICO: persiste 2–4 semanas após tratamento eficaz (hipersensibilidade aos ácaros mortos) — NÃO repetir o escabicida (dermatite irritativa); hidratante, hidrocortisona 1% (ou mometasona em maiores, fora da face) 7–14 d, anti-H1 (hidroxizina {{d;0.5;2;25;mL}} à noite); IMPETIGINIZAÇÃO: cefalexina {{d;12.5;50;500;mL}} 6/6 h 7 d (tratar 24–48 h antes/junto do escabicida); nódulos persistentes: corticoide tópico potente/intralesional; só repetir escabicida se LESÕES NOVAS (túneis/vesículas) após 2–4 semanas','PEDICULOSE DO COURO CABELUDO (Pediculus capitis): prurido occipital/retroauricular, lêndeas (ovos) aderidas firmemente a < 1 cm do couro cabeludo (viáveis; as distantes são vazias), piolhos vivos (diagnóstico definitivo — pente fino em cabelo molhado com condicionador é mais sensível que inspeção); NÃO transmite doença; infecção secundária/linfadenopatia por coçar','PEDICULOSE — PERMETRINA 1% loção/xampu (≥ 2 meses) é 1ª linha (resistência crescente): aplicar em cabelo lavado e úmido (toalha) por 10 min, enxaguar, pente fino; REPETIR em 7–9 dias (obrigatório — ovos); alternativas: IVERMECTINA 0,5% loção tópica (≥ 6 m; dose única 10 min — eficácia alta, sem resistência) ou IVERMECTINA VO 200 mcg/kg (≥ 15 kg) DU + repetir em 7–10 d (resistente/falha — Chosidow NEJM 2010); dimeticona 4% (≥ 6 m; física — sem resistência; 8 h ou 2 aplicações de 15 min com 7 d); malation 0,5% (≥ 6 a — inflamável); spinosad 0,9% (≥ 6 m); NÃO usar: lindano, querosene/inseticidas/álcool/vinagre (ineficazes/tóxicos), óleos "caseiros" sem evidência; tratar só quem tem piolhos vivos/lêndeas viáveis (não todos os contatos — mas examinar todos); REMOÇÃO MECÂNICA com pente fino (metal, dentes 0,2–0,3 mm) em cabelo molhado com condicionador a cada 2–3 dias por 2 semanas é parte essencial (isolada tem ~50% de sucesso)','Não é necessário afastar da escola após o 1º tratamento (AAP: "no-nit policies" não se justificam); não compartilhar pentes/bonés/travesseiros; lavar a quente/secar em secador ou guardar 2 semanas em saco fechado itens dos últimos 2 dias (piolhos morrem em 1–2 dias fora da cabeça; lêndeas não eclodem a < 30 °C)']}],casa:[{v:'USO TÓPICO — ESCABIOSE (TODOS da casa no MESMO dia)',i:[['Permetrina 5% loção (Keltrina®/Nedax® 5%) — 1ª escolha ≥ 2 meses','1–2 frascos de 60 mL por pessoa (adulto ~30 mL/aplicação; criança 10–20 mL)','À noite, após banho morno e pele seca, aplicar em TODO o corpo do pescoço para baixo (bebês e crianças pequenas: INCLUIR couro cabeludo, pescoço, face — evitar olhos/boca — e atrás das orelhas), com atenção a dobras, entre dedos das mãos e pés, punhos, axilas, umbigo, nádegas, genitais e embaixo das unhas (cortar e limpar antes); deixar agir 8–14 h (dormir) e lavar pela manhã; reaplicar nas mãos se lavar/der banho no bebê; REPETIR a aplicação completa após 7 dias. Tratar TODOS os moradores e contatos íntimos no mesmo dia, mesmo sem coceira'],['OU Enxofre precipitado 5–10% em vaselina (manipulado) — lactentes < 2 meses, gestantes se não houver permetrina','1 pote 100 g','Aplicar em todo o corpo à noite por 3 noites consecutivas, lavando pela manhã; repetir em 7 dias (cheiro forte, mancha roupas)'],['Hidratante sem perfume + Hidrocortisona 1% creme (prurido pós-tratamento)','1 pote + 1 bisnaga','Hidratante 2×/dia em todo o corpo por 2–4 semanas; hidrocortisona fina camada nas áreas de coceira/nódulos 2×/dia por 7–14 dias após o escabicida']]},{v:'USO ORAL — ESCABIOSE (alternativa/associação ≥ 15 kg; pediculose resistente)',i:[['Ivermectina 6 mg comprimido (≥ 15 kg; ≥ 5 anos pela bula)','{{p;1 comprimido para cada 30 kg por dose}} × 2 doses','Dar 200 mcg/kg ({{d;0.2;6;18;cp}}) em dose única em jejum (ou 2 h após refeição), com água; REPETIR a mesma dose após 7–14 dias; não usar em < 15 kg ou gestantes'],['Hidroxizina xarope 2 mg/mL (≥ 6 m) ou Dexclorfeniramina 0,4 mg/mL (≥ 2 a) — coceira/noite','1 frasco','Hidroxizina {{d;0.5;2;25;mL}} à noite (ou 8/8 h) por 7–14 dias se coceira intensa'],['Cefalexina suspensão 250 mg/5 mL — APENAS se lesões com pus/crostas amareladas (infecção)','1 frasco','Dar {{d;12.5;50;500;mL}} de 6/6 h por 7 dias']]},{v:'USO TÓPICO — PEDICULOSE (piolho) — só quem tem piolho vivo/lêndeas perto do couro cabeludo',i:[['Permetrina 1% loção ou xampu (Kwell®/Nedax®/Piolhol®) — ≥ 2 meses','1 frasco','Lavar o cabelo com xampu comum (sem condicionador), secar com toalha; aplicar a loção em todo o couro cabeludo e cabelo (atrás das orelhas/nuca), deixar 10 min, enxaguar; passar PENTE FINO; REPETIR a aplicação em 7–9 dias (obrigatório); não usar condicionador antes (reduz eficácia)'],['OU Ivermectina 0,5% loção (Sklice®) / Dimeticona 4% loção (Dimeti® — física, sem resistência) — ≥ 6 meses; se falha da permetrina','1 frasco','Ivermectina loção: aplicar em cabelo SECO cobrindo couro cabeludo, 10 min, enxaguar — dose única (sem pente obrigatório). Dimeticona: aplicar em cabelo seco, deixar 8 h (noite) ou 15 min, lavar; repetir em 7 dias'],['Pente fino de metal (dentes finos) + condicionador comum — REMOÇÃO MECÂNICA (essencial, com qualquer produto)','1 pente','Em cabelo molhado com bastante condicionador, dividir em mechas e passar o pente da raiz às pontas, limpando o pente em papel branco a cada passada; repetir TODA a cabeça a cada 2–3 dias por 2 semanas (até 3 passagens seguidas sem achar piolho); lêndeas presas: puxar com a unha/pente ou vinagre diluído (ajuda a soltar — não mata)'],['Ivermectina 6 mg VO (≥ 15 kg) — pediculose RESISTENTE/refratária a 2 tópicos','{{p;1 cp/30 kg}} × 2 doses','Dar 200 mcg/kg em dose única e repetir em 7–10 dias']]}],ori:['ESCABIOSE — todos da casa tratados NO MESMO DIA (inclusive quem não coça — pode estar incubando por 2–6 semanas); no dia do tratamento: lavar roupas de cama, toalhas, roupas e pelúcias usadas nos últimos 3 dias em água quente (≥ 60 °C) e secar ao sol/secador quente ou passar a ferro; o que não puder lavar: fechar em saco plástico por 72 h (ou 1 semana); aspirar sofá/colchão/cadeirinha do carro; não é necessário "dedetizar" a casa; animais domésticos NÃO transmitem a sarna humana','A COCEIRA CONTINUA por 2–4 semanas após o tratamento correto (reação aos ácaros mortos) — isso NÃO é falha; usar hidratante, hidrocortisona e anti-histamínico; só repetir o remédio se surgirem lesões NOVAS (bolinhas/túneis) após 2–4 semanas ou se orientado; nódulos (caroços) em axila/genital podem durar meses — são benignos','Volta à creche/escola 24 h após a 1ª aplicação (escabiose e piolho — não precisa esperar sumir as lêndeas); avisar a escola/creche para que outras crianças sejam examinadas e tratadas (surto)','PIOLHO: não é falta de higiene (prefere cabelo limpo); pega por contato cabeça-com-cabeça (selfies, abraços, dormir junto) — não pula nem voa; examinar toda a família com pente fino e tratar só quem tiver piolho vivo; repetir o tratamento em 7–9 dias é OBRIGATÓRIO; pente fino é o que realmente resolve (produto + pente); cabelo preso/trançado reduz contágio; lavar a quente/secar no secador pentes, escovas, bonés, fronhas, lençóis, capuz dos últimos 2 dias — ou guardar fechado 2 semanas; não usar querosene, inseticida, álcool, vinagre puro, "remédio de cachorro" (tóxicos/ineficazes)','Unhas curtas e limpas (escovar sob as unhas — ácaros/ovos); banho diário; não coçar (infecção/cicatriz); retorno em 2–4 semanas (escabiose) ou se piolhos vivos após 2 tratamentos (resistência — trocar o produto/ivermectina)'],al:['Feridas com pus, crostas amareladas ("mel"), vermelhidão quente que se espalha, febre, gânglios doloridos (infecção secundária — precisa de antibiótico)','Urina escura ou espumosa, inchaço nos olhos/pernas, pressão alta 1–3 semanas depois (glomerulonefrite após impetigo)','Crostas grossas/descamação espessa em mãos, pés, couro cabeludo, corpo com pouca coceira (sarna crostosa — altamente contagiosa; imunossuprimido/Down) → avaliação urgente','Lesões NOVAS (túneis/bolinhas) 4 semanas após o tratamento correto de todos (reinfestação/falha) ou coceira intensa que não permite dormir apesar do tratamento','Irritação intensa/queimação da pele após o produto, tontura, vômitos, convulsão (intoxicação — raro; nunca usar lindano/inseticida)'],ref:'IACS/European Guideline for the Management of Scabies 2017 (Salavastru) e IACS 2020 (critérios); CDC Scabies & Head Lice 2023/2024; AAP Clinical Report Head Lice 2022 (Nolt) e Red Book 2024; SBD/SBP — Escabiose e Pediculose 2019/2021 (Departamento de Dermatologia SBP); Cochrane 2018 (Rosumeck — permetrina × ivermectina) e 2016 (pediculose — Burgess); Chosidow NEJM 2010 (ivermectina oral no piolho); Engelman Lancet 2019 (surtos/MDA); Pariser NEJM 2012 (ivermectina loção); Heukelbach 2008; Thadanipon JAAD 2019 (meta-análise escabiose).'}
);
